const l=864e5;export function dayOfYear(t){return Math.floor((new Date(t.getFullYear(),t.getMonth(),t.getDate())-new Date(t.getFullYear(),0,1))/864e5)}export function isDaylightSaving(t){const o=new Date(t.getFullYear(),0,1).getTimezoneOffset(),n=new Date(t.getFullYear(),6,1).getTimezoneOffset();return t.getTimezoneOffset()<Math.max(o,n)}export function sunTimes(t){const n=6.1+1.3*Math.cos(2*Math.PI*(dayOfYear(t)-172)/365),c=11.95+(isDaylightSaving(t)?1:0);return{sunrise:c-n,sunset:c+n}}const f=t=>{const o=Math.min(1,Math.max(0,t));return o*o*(3-2*o)};export function mix(t,o,n){const c=Math.min(1,Math.max(0,n)),r=(e,u)=>e>>u&255,s=e=>Math.round(r(t,e)+(r(o,e)-r(t,e))*c);return s(16)<<16|s(8)<<8|s(0)}export function css(t){return`#${t.toString(16).padStart(6,"0")}`}export function lightAt(t,o=null){const n=o??t.getHours()+t.getMinutes()/60,{sunrise:c,sunset:r}=sunTimes(t),s=Math.min(f((n-c+.5)/1),f((r+.5-n)/1));let e="day";return s<=0?e="night":s<1&&(e=n<12?"dawn":"dusk"),{hour:n,daylight:s,phase:e,key:`${e}:${Math.round(s*8)}`}}const i={top:726320,bottom:2764618,sun:10466559,clouds:2895940},a={top:5208499,bottom:13483974,sun:16757611,clouds:16760732},h={top:8368861,bottom:14937327,sun:16773336,clouds:16777215};export const OFFICE_HOURS=[[0,.14],[3,.05],[4,.05],[6.5,.24],[8,.42],[17,.42],[20,.34],[24,.14]];export function officesLit(t,o=OFFICE_HOURS){const n=(t%24+24)%24;for(let c=1;c<o.length;c++){const[r,s]=o[c];if(n<=r){const[e,u]=o[c-1];return u+(s-u)*(n-e)/(r-e)}}return o[o.length-1][1]}export const GOLDEN_HOUR={high:18,low:5};export function goldenHour(t){const o=t*180/Math.PI;return f((GOLDEN_HOUR.high-o)/(GOLDEN_HOUR.high-GOLDEN_HOUR.low))}export function lighting(t,o=null){const n=t.daylight,c=t.phase==="dawn"||t.phase==="dusk"?Math.sin(n*Math.PI):0,r=Math.max(c,o?goldenHour(o.sunHeight)*n:0),s=(e,u=c)=>mix(mix(i[e],h[e],n),a[e],u*.7);return{skyTop:s("top"),skyBottom:s("bottom"),sunColor:s("sun",r),clouds:s("clouds",r),warm:r,sun:.12+1.4*n,hemi:.22+.7*n,fill:.12+.23*n,bounce:.06+.45*n,cityLights:1-n,offices:officesLit(t.hour),stars:f((.35-n)/.35),moonShine:1-.65*n,halo:.3+.7*r,cityNear:mix(1844019,5991293,n),cityFar:mix(2436160,8690093,n)}}
